} else if (key === "Escape") {
  // Hitting Escape:
  // - Closes submenu.
  // - Moves focus to parent menubar item.
  preventEvent(event);
  // Close the current submenu via its toggle, which will also focus the parent menu item.
  const parentMenu = this.elements.parentMenu;
  if (parentMenu) {
    const parentMenuItem = parentMenu.elements.currentMenuItem;
    if (parentMenuItem && parentMenuItem.elements.toggle) {
      parentMenuItem.elements.toggle.close();
    }
  }
}
